import math
import random

def schedule(betas):
    if not betas or any(type(b) not in (int, float) or not math.isfinite(b) or not 0 < b < 1 for b in betas):
        raise ValueError('betas must be finite and strictly between zero and one')
    product, cumulative = 1.0, []
    for beta in betas:
        product *= 1 - beta
        if product == 0:
            raise ValueError('cumulative signal underflow; use a log-space implementation')
        cumulative.append(product)
    return cumulative

def forward(x0, noise, alpha_bar):
    if not all(type(v) in (int, float) and math.isfinite(v) for v in (x0, noise, alpha_bar)) or not 0 < alpha_bar < 1:
        raise ValueError('finite values and alpha_bar in (0,1) required')
    value = math.sqrt(alpha_bar) * x0 + math.sqrt(1-alpha_bar) * noise
    if not math.isfinite(value):
        raise ValueError('forward arithmetic overflow')
    return value

def oracle_recover(xt, known_noise, alpha_bar):
    # Uses fixture noise; not a learned denoiser or reverse sampling algorithm.
    if not all(type(v) in (int, float) and math.isfinite(v) for v in (xt, known_noise, alpha_bar)) or not 0 < alpha_bar < 1:
        raise ValueError('finite values and alpha_bar in (0,1) required')
    value = (xt - math.sqrt(1-alpha_bar)*known_noise) / math.sqrt(alpha_bar)
    if not math.isfinite(value):
        raise ValueError('oracle arithmetic overflow')
    return value

def main():
    cumulative = schedule([.1, .2, .3])
    assert all(a > b for a, b in zip(cumulative, cumulative[1:]))
    assert math.isclose(cumulative[-1], .504)
    assert math.isclose(forward(2, -1, .64), 1)
    assert math.isclose(oracle_recover(1, -1, .64), 2)
    assert not math.isclose(oracle_recover(1, 0, .64), 2), 'wrong noise must change recovery'
    rng = random.Random(7)
    fixtures = [(rng.uniform(-3, 3), rng.gauss(0, 1)) for _ in range(30)]
    for alpha in cumulative:
        for clean, noise in fixtures:
            assert math.isclose(oracle_recover(forward(clean, noise, alpha), noise, alpha), clean, abs_tol=1e-12)
    for invalid in ([], [0], [1], [-.1], [float('nan')], [True], [.9]*1000):
        try:
            schedule(invalid)
        except ValueError:
            pass
        else:
            raise AssertionError('invalid schedule accepted')
    for operation, args in ((forward, (1.7e308, 1.7e308, .5)), (oracle_recover, (1e308, 0, 1e-300))):
        try:
            operation(*args)
        except ValueError:
            pass
        else:
            raise AssertionError('non-finite arithmetic accepted')
    print('day16 PASS: cumulative schedule, oracle identity, wrong-noise failure, invalid betas')

if __name__ == '__main__':
    main()

import math

def finite(values):
    return all(type(v) in (int, float) and math.isfinite(v) for v in values)

def route(hidden, matrix, bias, k):
    if not hidden or not matrix or len(matrix) != len(bias) or not finite(hidden + bias):
        raise ValueError('invalid router dimensions or values')
    if any(len(row) != len(hidden) or not finite(row) for row in matrix):
        raise ValueError('invalid matrix row')
    if type(k) is not int or not 1 <= k <= len(matrix):
        raise ValueError('k outside expert range')
    logits = [sum(w*x for w, x in zip(row, hidden)) + b for row, b in zip(matrix, bias)]
    if not finite(logits):
        raise ValueError('router arithmetic overflow')
    selected = sorted(range(len(logits)), key=lambda i: (-logits[i], i))[:k]
    maximum = max(logits[i] for i in selected)
    exp_scores = [math.exp(logits[i]-maximum) for i in selected]
    weights = [v/sum(exp_scores) for v in exp_scores]
    return selected, weights

def dispatch(tokens, matrix, bias, capacity):
    if type(capacity) is not int or capacity < 1:
        raise ValueError('positive integer capacity required')
    loads = [0]*len(matrix)
    accepted, overflow = [], []
    for token_id, hidden in enumerate(tokens):
        selected, weights = route(hidden, matrix, bias, 1)
        expert = selected[0]
        if loads[expert] >= capacity:
            overflow.append({'token': token_id, 'expert': expert, 'reason': 'capacity'})
        else:
            loads[expert] += 1
            accepted.append({'token': token_id, 'expert': expert, 'gate': weights[0]})
    assert len(accepted)+len(overflow) == len(tokens)
    return accepted, overflow, loads

def main():
    matrix, bias = [[1., 0.], [0., 1.], [-1., 0.]], [0., .5, 0.]
    selected, weights = route([1., 0.], matrix, bias, 2)
    assert selected == [0, 1]
    assert math.isclose(weights[0], .6224593312018546)
    assert math.isclose(sum(weights), 1)
    assert route([1., 0.], matrix, [0., 2., 0.], 1)[0] == [1]
    assert route([0., 0.], matrix, [0., 0., 0.], 2)[0] == [0, 1]
    # Invented scalar experts; no claimed human-language specialization.
    expert_outputs = [10., 20., 30.]
    output = sum(g*expert_outputs[e] for e, g in zip(selected, weights))
    assert math.isclose(output, 13.775406687981454)
    accepted, overflow, loads = dispatch([[1.,0.]]*3, matrix, bias, 1)
    assert len(accepted) == 1 and len(overflow) == 2 and loads == [1,0,0]
    for hidden, k in (([float('nan'),0.],1), ([1.],1), ([1.,0.],0), ([1.,0.],True)):
        try:
            route(hidden, matrix, bias, k)
        except ValueError:
            pass
        else:
            raise AssertionError('invalid router input accepted')
    print('day17 PASS: affine bias, top-k, ties, normalized gates, explicit overflow')

if __name__ == '__main__':
    main()

import math

def loss(x):
    return (x*x-1)**2

def gradient(x):
    return 4*x*(x*x-1)

def descend(initial, step=.05, iterations=120):
    if type(initial) not in (int, float) or not math.isfinite(initial):
        raise ValueError('finite initial point required')
    if type(step) not in (int, float) or not math.isfinite(step) or step <= 0:
        raise ValueError('finite positive step required')
    if type(iterations) is not int or iterations < 0:
        raise ValueError('nonnegative integer iterations required')
    x, history = initial, [loss(initial)]
    for _ in range(iterations):
        x -= step * gradient(x)
        if not math.isfinite(x) or abs(x) > 1e20:
            raise ArithmeticError('unstable trajectory')
        history.append(loss(x))
    return x, history

def main():
    assert loss(-1) == loss(1) == 0
    assert gradient(0) == 0 and loss(0) == 1
    stuck, unchanged = descend(0)
    assert stuck == 0 and set(unchanged) == {1}
    positive, history = descend(.1)
    negative, _ = descend(-.1)
    assert math.isclose(positive, 1, abs_tol=1e-8)
    assert math.isclose(negative, -1, abs_tol=1e-8)
    assert all(b <= a+1e-14 for a,b in zip(history, history[1:]))
    # Saddle f(x,y)=x*x-y*y: gradient=(2*x,-2*y), Hessian=diag(2,-2).
    saddle = lambda x,y: x*x-y*y
    assert saddle(0,.1) < saddle(0,0) < saddle(.1,0)
    assert (2*0,-2*0) == (0,0)
    try:
        descend(.5, 5, 20)
    except ArithmeticError:
        pass
    else:
        raise AssertionError('large-step instability not reported')
    for args in ((float('nan'), .05, 1), (0, 0, 1), (0,.05,True)):
        try:
            descend(*args)
        except ValueError:
            pass
        else:
            raise AssertionError('invalid optimizer input accepted')
    print('day19 PASS: stationary maximum, two global minima, saddle directions, unstable step')

if __name__ == '__main__':
    main()

import math

def ternarize(weights, threshold):
    if type(threshold) not in (int,float) or not math.isfinite(threshold) or threshold < 0:
        raise ValueError('nonnegative finite threshold required')
    if not weights or any(type(w) not in (int,float) or not math.isfinite(w) for w in weights):
        raise ValueError('nonempty finite weights required')
    return [-1 if w < -threshold else 1 if w > threshold else 0 for w in weights]

def ternary_dot(symbols, values):
    if not symbols or len(symbols) != len(values):
        raise ValueError('matching nonempty vectors required')
    if any(type(s) is not int or s not in (-1,0,1) for s in symbols):
        raise ValueError('ternary integer symbols required')
    if any(type(v) is not int for v in values):
        raise ValueError('integer fixture activations required')
    total = 0
    for symbol, value in zip(symbols, values):
        if symbol == 1:
            total += value
        elif symbol == -1:
            total -= value
    return total

def main():
    weights = [-.9,-.2,.01,.3,.8,1.1]
    values = [2,3,4,5,6,7]
    symbols = ternarize(weights,.25)
    assert symbols == [-1,0,0,1,1,1]
    result = ternary_dot(symbols, values)
    assert result == 16
    assert result == sum(s*v for s,v in zip(symbols, values))
    original = sum(w*v for w,v in zip(weights,values))
    assert math.isclose(original, 11.64)
    assert math.isclose(result-original,4.36)
    assert ternarize([-.25,0,.25],.25) == [0,0,0]
    assert math.isclose(math.log2(3),1.584962500721156)
    # This comparison excludes scales, metadata, other tensors and alignment.
    ideal_bits = len(weights)*math.log2(3)
    naive_packed_bits = len(weights)*2
    assert ideal_bits < naive_packed_bits < len(weights)*16
    for weights_bad in ([],[float('nan')],[True]):
        try:
            ternarize(weights_bad,.25)
        except ValueError:
            pass
        else:
            raise AssertionError('invalid weights accepted')
    for symbols_bad, values_bad in (([2],[1]),([True],[1]),([1],[1,2]),([1],[1.5])):
        try:
            ternary_dot(symbols_bad,values_bad)
        except ValueError:
            pass
        else:
            raise AssertionError('invalid arithmetic boundary accepted')
    print('day20 PASS: ternary alphabet, add/subtract/skip, explicit error, information vs packing')

if __name__ == '__main__':
    main()
